const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const repoRoot = path.resolve(__dirname, '..');
const distDir = path.join(repoRoot, 'miracode-web', 'dist');
const distHtmlPath = path.join(distDir, 'index.html');
const outPath = path.join(
  repoRoot,
  'src',
  'screens',
  'MiraCodeScreen',
  'miracodeHtmlBundle.ts',
);

if (!fs.existsSync(distHtmlPath)) {
  console.error(`Missing built web bundle at: ${distHtmlPath}`);
  console.error('Run "npm run build" inside miracode-web/ first.');
  process.exit(1);
}

let html = fs.readFileSync(distHtmlPath, 'utf8');

// Inline external stylesheets built by Vite into <style> tags for self-contained WKWebView loading.
html = html.replace(
  /<link\b[^>]*rel=["']stylesheet["'][^>]*href=["']([^"']+)["'][^>]*>/gi,
  (_match, href) => {
    const cleanHref = href.replace(/^\.\//, '').replace(/^\//, '');
    const assetPath = path.join(distDir, cleanHref);
    if (!fs.existsSync(assetPath)) {
      console.error(`Referenced stylesheet not found: ${assetPath}`);
      process.exit(1);
    }
    const css = fs
      .readFileSync(assetPath, 'utf8')
      .replace(/<\/style/gi, () => '<\\/style');
    return `<style>\n${css}\n</style>`;
  },
);

// Extract external scripts built by Vite and insert before </body> using slice (never string .replace,
// which expands $`, $&, $', $$ inside minified JavaScript bundles!).
const inlinedScripts = [];
const rawJsBlocks = [];
html = html.replace(
  /<script\b([^>]*?)src=["']([^"']+)["']([^>]*)><\/script>/gi,
  (_match, beforeSrc, src, afterSrc) => {
    const cleanSrc = src.replace(/^\.\//, '').replace(/^\//, '');
    const assetPath = path.join(distDir, cleanSrc);
    if (!fs.existsSync(assetPath)) {
      console.error(`Referenced script not found: ${assetPath}`);
      process.exit(1);
    }
    const js = fs
      .readFileSync(assetPath, 'utf8')
      .replace(/<\/script/gi, () => '<\\/script');
    rawJsBlocks.push(js);
    const isModule = /\btype=["']module["']/i.test(`${beforeSrc} ${afterSrc}`);
    const typeAttr = isModule ? ' type="module"' : '';
    inlinedScripts.push(`<script${typeAttr}>\n${js}\n</script>`);
    return '';
  },
);

if (inlinedScripts.length > 0) {
  const scriptBlock = inlinedScripts.join('\n');
  const lowerHtml = html.toLowerCase();
  const bodyCloseIdx = lowerHtml.lastIndexOf('</body>');
  if (bodyCloseIdx !== -1) {
    html =
      html.slice(0, bodyCloseIdx) +
      `${scriptBlock}\n  ` +
      html.slice(bodyCloseIdx);
  } else {
    html += `\n${scriptBlock}`;
  }
}

if (
  html.includes('fonts.googleapis.com') ||
  html.includes('fonts.gstatic.com')
) {
  console.error(
    'Offline bundle check failed: Google Fonts URL detected in dist/index.html',
  );
  process.exit(1);
}

if (
  /\bsrc=["']\.?\/assets\//i.test(html) ||
  /\bhref=["']\.?\/assets\//i.test(html)
) {
  console.error(
    'Offline bundle check failed: un-inlined ./assets/ reference remains in HTML',
  );
  process.exit(1);
}

// Verify HTML structural integrity outside inlined <script> blocks
const htmlWithoutScripts = html.replace(
  /<script\b[^>]*>[\s\S]*?<\/script>/gi,
  () => '',
);
const doctypeCount = (htmlWithoutScripts.match(/<!doctype/gi) || []).length;
const bodyCloseCount = (htmlWithoutScripts.match(/<\/body>/gi) || []).length;
if (doctypeCount !== 1 || bodyCloseCount !== 1) {
  console.error(
    `HTML integrity check failed: doctypeCount=${doctypeCount}, bodyCloseCount=${bodyCloseCount}`,
  );
  process.exit(1);
}

// Parse every inlined JS block with esbuild to guarantee zero syntax corruption
const esbuildPath = path.join(
  repoRoot,
  'miracode-web',
  'node_modules',
  'esbuild',
);
if (fs.existsSync(esbuildPath)) {
  const esbuild = require(esbuildPath);
  for (let i = 0; i < rawJsBlocks.length; i++) {
    try {
      esbuild.transformSync(rawJsBlocks[i], {
        loader: 'js',
        format: 'esm',
      });
    } catch (err) {
      console.error(`Syntax error in inlined JS block ${i}:`, err.message);
      process.exit(1);
    }
  }
}

const bundleHash = crypto
  .createHash('sha256')
  .update(html, 'utf8')
  .digest('hex')
  .slice(0, 12);
const base64Html = Buffer.from(html, 'utf8').toString('base64');

const output = `// Auto-generated by scripts/build-miracode-bundle.js. Do not edit manually.
export const MIRACODE_BUNDLE_HASH = ${JSON.stringify(bundleHash)};
export const MIRACODE_HTML_BASE64 = ${JSON.stringify(base64Html)};
`;

fs.mkdirSync(path.dirname(outPath), {recursive: true});
fs.writeFileSync(outPath, output, 'utf8');

const kb = (Buffer.byteLength(html, 'utf8') / 1024).toFixed(1);
console.log(
  `Wrote ${outPath} (${kb} KB self-contained HTML, hash=${bundleHash}, syntax verified)`,
);
